const BHR = (() => {
  'use strict';
  const RECEIPTS_KEY='bhr_submission_receipts_v4';
  const CONSENT_VERSION='2026-08-29-v1';
  const banks=['Bank of America, N.A.','JPMorgan Chase Bank, N.A.','Capital One, N.A.','Wells Fargo Bank, N.A.','Citibank, N.A.','U.S. Bank National Association','PNC Bank, National Association','Truist Bank','Other / not sure'];
  const issues=['Credit reporting error','Debt collection not owed','Checking/savings account problem','Account freeze or closure','Unauthorized transfer or scam','Credit card billing/rewards dispute','Mortgage or loan servicing','Identity theft/account takeover','Discrimination/unfair treatment','Other'];
  const remedies=['Refund/reimburse loss','Correct credit reporting','Unfreeze/reopen account','Provide written explanation','Stop collection/negative reporting','Investigate unauthorized transfer','Preserve records','Escalate to executive office','Other'];
  const qs=(s,r=document)=>r.querySelector(s), qsa=(s,r=document)=>[...r.querySelectorAll(s)];
  function options(values){return values.map(v=>{const o=document.createElement('option');o.value=v;o.textContent=v;return o})}
  function fill(){qsa('[data-banks]').forEach(x=>x.replaceChildren(...options(banks)));qsa('[data-issues]').forEach(x=>x.replaceChildren(...options(issues)));qsa('[data-remedies]').forEach(x=>x.replaceChildren(...options(remedies)))}
  function toast(message,error=false){const e=qs('#toast');if(!e)return;e.textContent=message;e.dataset.kind=error?'error':'success';e.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>e.classList.remove('show'),4500)}
  function sensitive(text){return /(\b\d{3}-\d{2}-\d{4}\b)|(\b\d{9}\b)|(\b(?:\d[ -]*?){12,19}\b)/.test(text||'')}
  function payload(form){const d=Object.fromEntries(new FormData(form).entries());d.type=form.dataset.type||'consumer-report';d.consentVersion=CONSENT_VERSION;d.pageUrl=location.href;return d}
  function userText(d){return ['name','institution','issue','state','amount','timeline','evidence','story','summary','remedy','credentials','area','conflictDisclosure','mediaOutlet'].map(k=>d[k]||'').join('\n')}
  function receipts(){try{const a=JSON.parse(localStorage.getItem(RECEIPTS_KEY)||'[]');return Array.isArray(a)?a:[]}catch{return[]}}
  function saveReceipt(r){const a=receipts();a.unshift(r);localStorage.setItem(RECEIPTS_KEY,JSON.stringify(a.slice(0,25)))}
  function renderReceipts(){const box=qs('#localReports');if(!box)return;const a=receipts();box.replaceChildren();if(!a.length){const p=document.createElement('p');p.className='muted';p.textContent='No submission receipts saved on this device.';box.append(p);return}a.slice(0,8).forEach(r=>{const el=document.createElement('div');el.className='receipt-card';const strong=document.createElement('strong');strong.textContent=r.institution||'Private report';const p=document.createElement('p');p.className='micro';p.textContent=`${r.reportId} · ${new Date(r.createdAt).toLocaleDateString()}`;el.append(strong,p);box.append(el)})}
  async function loadTurnstile(){try{const res=await fetch('/api/public-config',{headers:{Accept:'application/json'}});if(!res.ok)return;const c=await res.json();if(!c.turnstileSiteKey)return;await new Promise((resolve,reject)=>{if(window.turnstile)return resolve();const s=document.createElement('script');s.src='https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit';s.async=true;s.defer=true;s.onload=resolve;s.onerror=reject;document.head.append(s)});qsa('[data-turnstile-slot]').forEach(slot=>{if(slot.dataset.rendered||!window.turnstile)return;window.turnstile.render(slot,{sitekey:c.turnstileSiteKey,theme:'dark',callback(token){const f=slot.closest('form');const i=qs('[name="turnstileToken"]',f);if(i)i.value=token},'expired-callback'(){const f=slot.closest('form');const i=qs('[name="turnstileToken"]',f);if(i)i.value=''}});slot.dataset.rendered='true'})}catch{}}
  async function submit(form){const data=payload(form),status=qs('[data-form-status]',form),button=qs('button[type="submit"]',form);if(data.website){form.reset();return}if(sensitive(userText(data))){toast('Remove SSNs, full account/card numbers, or other long sensitive numbers.',true);if(status)status.textContent='Submission blocked until sensitive numbers are removed.';return}if(button){button.disabled=true;button.dataset.old=button.textContent;button.textContent='Submitting securely…'}try{const res=await fetch('/api/submit-report',{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify(data)});const out=await res.json().catch(()=>({}));if(!res.ok)throw new Error(out.error||'Submission failed.');saveReceipt({reportId:out.reportId,institution:data.institution||'',createdAt:new Date().toISOString()});form.reset();renderReceipts();toast(`Submitted privately. Receipt: ${out.reportId}`);if(status)status.textContent=`Submission received. Save receipt: ${out.reportId}.`}catch(err){toast(err.message||'Submission failed.',true);if(status)status.textContent=`${err.message||'Submission failed.'} Your form remains filled so you can retry.`}finally{if(button){button.disabled=false;button.textContent=button.dataset.old||'Submit'}}}
  function searchForms(){qsa('[data-institution-search]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const input=qs('[name="q"]',form);const q=input?.value.trim();if(q)location.href=`research.html?q=${encodeURIComponent(q)}`}))}
  function donationLinks(){const links=window.BHR_CONFIG?.donationLinks||{};qsa('[data-donation-tier]').forEach(a=>{const u=links[a.dataset.donationTier];if(u){a.href=u;a.target='_blank';a.rel='noopener noreferrer'}else{a.removeAttribute('href');a.setAttribute('aria-disabled','true');a.textContent='Payment link not configured';a.classList.add('btn')}})}
  function init(){fill();renderReceipts();loadTurnstile();searchForms();donationLinks();qsa('form[data-bhr-form]').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();submit(f)}));qs('#clearReceipts')?.addEventListener('click',()=>{localStorage.removeItem(RECEIPTS_KEY);renderReceipts();toast('Receipt metadata cleared.')})}
  return {init,_test:{sensitive}};
})();
document.addEventListener('DOMContentLoaded',BHR.init);
